import collections

def transform(grid):
    H = len(grid)
    if H == 0: return grid
    W = len(grid[0])

    # Find background color (most frequent)
    bg_counts = collections.Counter()
    for row in grid:
        for x in row:
            bg_counts[x] += 1
    bg = max(bg_counts, key=bg_counts.get)

    res = [row[:] for row in grid]

    # Iterate over all possible frames
    # A frame is defined by top-left (r1, c1) and bottom-right (r2, c2)
    # Must enclose an interior of size at least 1x1, so size >= 3x3
    for r1 in range(H):
        for c1 in range(W):
            start_color = grid[r1][c1]
            if start_color == bg:
                continue

            # Minimum frame size 3x3 means r2 >= r1+2, c2 >= c1+2
            for r2 in range(r1 + 2, H):
                for c2 in range(c1 + 2, W):
                    # Check if border is uniform start_color and interior is bg
                    border_color = start_color

                    # Check Top row
                    top_ok = True
                    for c in range(c1, c2 + 1):
                        if grid[r1][c] != border_color:
                            top_ok = False; break
                    if not top_ok: continue

                    # Check Bottom row
                    bot_ok = True
                    for c in range(c1, c2 + 1):
                        if grid[r2][c] != border_color:
                            bot_ok = False; break
                    if not bot_ok: continue

                    # Check Left col
                    left_ok = True
                    for r in range(r1, r2 + 1):
                        if grid[r][c1] != border_color:
                            left_ok = False; break
                    if not left_ok: continue

                    # Check Right col
                    right_ok = True
                    for r in range(r1, r2 + 1):
                        if grid[r][c2] != border_color:
                            right_ok = False; break
                    if not right_ok: continue

                    # Check Interior
                    interior_ok = True
                    for r in range(r1 + 1, r2):
                        for c in range(c1 + 1, c2):
                            if grid[r][c] != bg:
                                interior_ok = False; break
                        if not interior_ok: break

                    if interior_ok:
                        # Mark border for change to 3
                        for r in range(r1, r2 + 1):
                            for c in range(c1, c2 + 1):
                                if r == r1 or r == r2 or c == c1 or c == c2:
                                    res[r][c] = 3
    return res
